import org.apache.commons.lang3.time.DurationFormatUtils;
import java.util.Calendar;
import java.util.TimeZone;
import java.util.Date;

public class Probe {
    public static void main(String[] args) throws Exception {
        p("formatDuration(0, 'ddd:HH:mm:ss.SSS')", DurationFormatUtils.formatDuration(0, "ddd:HH:mm:ss.SSS"));
        long totalMillis = 183845006L;
        p("formatDuration(totalMillis, pattern, true)", DurationFormatUtils.formatDuration(totalMillis, "d'd'H'h'm'm's's'S'S'"));
        p("formatDuration(totalMillis, pattern, false)", DurationFormatUtils.formatDuration(totalMillis, "d'd'H'h'm'm's's'S'S'", false));
        p("formatDuration(Long.MAX_VALUE, 'd')", DurationFormatUtils.formatDuration(Long.MAX_VALUE, "d"));
        try {
            DurationFormatUtils.formatDuration(-1, "d");
            System.out.println("NO EXCEPTION");
        } catch (IllegalArgumentException e) {
            System.out.println("formatDuration(-1): IAE: " + e.getMessage());
        }
        p("formatDurationHMS(0)", DurationFormatUtils.formatDurationHMS(0));
        p("formatDurationHMS(1)", DurationFormatUtils.formatDurationHMS(1));
        p("formatDurationHMS(3661001)", DurationFormatUtils.formatDurationHMS(3661001));
        p("formatDurationISO(0)", DurationFormatUtils.formatDurationISO(0));
        p("formatDurationISO(totalMillis)", DurationFormatUtils.formatDurationISO(totalMillis));

        p("formatDurationWords(0,false,false)", DurationFormatUtils.formatDurationWords(0, false, false));
        p("formatDurationWords(0,true,true)", DurationFormatUtils.formatDurationWords(0, true, true));
        p("formatDurationWords(0,true,false)", DurationFormatUtils.formatDurationWords(0, true, false));
        p("formatDurationWords(0,false,true)", DurationFormatUtils.formatDurationWords(0, false, true));
        p("formatDurationWords(1000,true,true)", DurationFormatUtils.formatDurationWords(1000, true, true));
        p("formatDurationWords(60000,true,true)", DurationFormatUtils.formatDurationWords(60000, true, true));
        p("formatDurationWords(3600000,true,true)", DurationFormatUtils.formatDurationWords(3600000, true, true));
        p("formatDurationWords(86400000,true,true)", DurationFormatUtils.formatDurationWords(86400000, true, true));
        p("formatDurationWords(65000,true,true)", DurationFormatUtils.formatDurationWords(65000, true, true));
        p("formatDurationWords(totalMillis,false,false)", DurationFormatUtils.formatDurationWords(totalMillis, false, false));
        p("formatDurationWords(totalMillis,true,true)", DurationFormatUtils.formatDurationWords(totalMillis, true, true));

        TimeZone utc = TimeZone.getTimeZone("UTC");
        Calendar c1 = Calendar.getInstance(utc);
        c1.clear();
        c1.set(2020, Calendar.JANUARY, 15, 10, 0, 0);
        Calendar c2 = Calendar.getInstance(utc);
        c2.clear();
        c2.set(2020, Calendar.MARCH, 10, 12, 30, 15);
        long start = c1.getTimeInMillis();
        long end = c2.getTimeInMillis();
        p("formatPeriod full", DurationFormatUtils.formatPeriod(start, end, "yyyy'-'MM'-'dd'T'HH':'mm':'ss", true, utc));
        p("formatPeriod yMd", DurationFormatUtils.formatPeriod(start, end, "y'y'M'M'd'd'", true, utc));
        p("formatPeriod Md only (no y)", DurationFormatUtils.formatPeriod(start, end, "M'M'd'd'", true, utc));
        p("formatPeriod d only", DurationFormatUtils.formatPeriod(start, end, "d'd'", true, utc));
        p("formatPeriodISO", DurationFormatUtils.formatPeriodISO(start, end));
        p("formatPeriod 3-arg default", DurationFormatUtils.formatPeriod(start, end, "d'd'H'h'm'm's's'"));

        try {
            DurationFormatUtils.formatPeriod(end, start, "d");
            System.out.println("NO EXCEPTION formatPeriod");
        } catch (IllegalArgumentException e) {
            System.out.println("formatPeriod(start>end): IAE: " + e.getMessage());
        }

        // same start/end
        p("formatPeriod same", DurationFormatUtils.formatPeriod(start, start, "y'y'M'M'd'd'H'h'm'm's's'", true, utc));

        // lexx / Token via reflection not needed since same package tests can call directly when placed in package.
    }

    static void p(String label, String value) {
        System.out.println(label + " => [" + value + "]");
    }
}

